classDiagram
    class Controller {
        +String inputBundle
        +compressInput()
    }
    class AddressRegister {
        +String compressedInputLocation
        +identifyMemoryLocation()
    }
    class ActivationMemory {
        +String inputData
        +String compressedInputData
    }
    class ParameterMemory {
        +String weightValues
    }
    class CalculationUnit {
        +multiplyMatrices()
    }
    Controller --> AddressRegister : "입력 묶음을 처리하여"
    AddressRegister --> ActivationMemory : "메모리 위치를 저장하여"
    ActivationMemory --> ParameterMemory : "가중치 값을 저장하는"
